rng=np.random.default_rng(1618033)
p=20;cont=[0]+list(range(10,20))
lo=np.array([-4.2]+[0.]*19);hi=np.array([3.]+[1.]*9+[10.]*10)
mu=(lo+hi)/2;sc=(hi-lo)/2
knots={0:[-3.,-1.5,-.6,0.,1.5]}
for j in range(10,20):knots[j]=[2.,4.,5.,6.,8.]
desc=[('const',)]
for j in range(p):
    desc.append(('linear',j))
    if j in cont:
        for k in knots[j]:desc.append(('hinge',j,k))
for j in range(p):
    for k in range(j+1,p):
        for a in range(2 if j in cont else 1):
            for b in range(2 if k in cont else 1):desc.append(('pair',j,k,a,b))
def draw(n):
    X=rng.uniform(0,10,(n,p));X[:,0]=rng.uniform(-4.2,3,n);X[:,1:10]=rng.integers(0,2,(n,9))
    return X
def design(X):
    Z=(X-mu)/sc;V=2*(abs(Z)-.5)
    cols=[]
    for d in desc:
        if d[0]=='const':cols.append(np.ones(len(X)))
        elif d[0]=='linear':cols.append(Z[:,d[1]])
        elif d[0]=='hinge':cols.append(np.maximum(X[:,d[1]]-d[2],0)/sc[d[1]])
        else:
            j,k,a,b=d[1:]
            cols.append((V[:,j] if a else Z[:,j])*(V[:,k] if b else Z[:,k]))
    return np.array(cols).T
m=len(desc);G=np.zeros((m,m));rhs=np.zeros(m)
for it in range(12):
    X=draw(20000);A=design(X);y=predict(X).ravel()
    G+=A.T@A;rhs+=A.T@y
coef=np.linalg.solve(G,rhs)
score=np.zeros(m)
for i,d in enumerate(desc):
    if d[0]=='pair':
        s=(1/np.sqrt(3) if d[1] in cont else 1)*(1/np.sqrt(3) if d[2] in cont else 1)
        score[i]=abs(coef[i])*s
ids=[i for i,d in enumerate(desc) if d[0]!='pair' or score[i]>=.004]
cf=np.linalg.solve(G[np.ix_(ids,ids)],rhs[ids])
X=draw(30000);A=design(X);y=predict(X).ravel()
yh=A[:,ids]@cf;err=yh-y
print('FIT',len(ids),'rmse',float(np.sqrt(np.mean(err*err))),'mae',float(abs(err).mean()),'r2',float(1-np.mean(err*err)/np.var(y)),'probmae',float(np.mean(abs(1/(1+np.exp(-yh))-1/(1+np.exp(-y))))),'p95log',float(np.quantile(abs(err),.95)),'maxlog',float(abs(err).max()))
